def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 1, "<>": 1, "<": 1, "<=": 1, ">": 1, ">=": 1,
        "+": 2, "-": 2,
        "*": 3, "/": 3,
        "neg": 4,
        ":": 5,
    }
    token_pattern = re.compile(
        r"\d+|[A-Z]+[0-9]*|<>|<=|>=|[-+*/():,=<>]"
    )

    def parse(formula):
        tokens = token_pattern.findall(formula)
        nodes = []
        operators = []

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                nodes.append(("neg", nodes.pop()))
                return

            right = nodes.pop()
            left = nodes.pop()
            if op == ":":
                nodes.append(("range", left[1], right[1]))
            else:
                nodes.append((op, left, right))

        expecting_operand = True
        i = 0
        while i < len(tokens):
            token = tokens[i]

            if token in functions:
                # The following token is the function's opening parenthesis.
                operators.append((token, len(nodes)))
                expecting_operand = True
                i += 2
                continue

            if token == "(":
                operators.append((None, len(nodes)))
                expecting_operand = True
            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expecting_operand = True
            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                function, base = operators.pop()
                if function is not None:
                    arguments = tuple(nodes[base:])
                    del nodes[base:]
                    nodes.append((function, arguments))
                expecting_operand = False
            elif token[0].isdigit():
                nodes.append(("num", int(token)))
                expecting_operand = False
            elif token[0].isalpha():
                nodes.append(("ref", token))
                expecting_operand = False
            elif token == "-" and expecting_operand:
                operators.append("neg")
            else:
                while (
                    operators
                    and isinstance(operators[-1], str)
                    and precedence[operators[-1]] >= precedence[token]
                ):
                    reduce_operator()
                operators.append(token)
                expecting_operand = True

            i += 1

        while operators:
            reduce_operator()
        return nodes[0]

    expressions = {}
    for name, content in cells.items():
        content = content.strip()
        expressions[name] = (
            parse(content[1:])
            if content.startswith("=")
            else ("num", int(content))
        )

    def argument_nodes(arguments):
        for node in arguments:
            if node[0] != "range":
                yield node
                continue

            first, last = node[1], node[2]
            c1, c2 = sorted((ord(first[0]), ord(last[0])))
            r1, r2 = sorted((int(first[1:]), int(last[1:])))

            for row in range(r1, r2 + 1):
                for column in range(c1, c2 + 1):
                    name = chr(column) + str(row)
                    if name in cells:
                        yield ("ref", name)

    results = {}
    active = set()

    for root in cells:
        if root in results:
            continue

        tasks = [("cell", root)]
        values = []

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in results:
                    values.append(results[name])
                elif name not in cells:
                    values.append(0)
                elif name in active:
                    values.append("#CYCLE!")
                else:
                    active.add(name)
                    tasks.append(("finish_cell", name))
                    tasks.append(("eval", expressions[name]))

            elif kind == "finish_cell":
                name = task[1]
                results[name] = values[-1]
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                op = node[0]

                if op == "num":
                    values.append(node[1])
                elif op == "ref":
                    tasks.append(("cell", node[1]))
                elif op == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))
                elif op == "IF":
                    condition, then_branch, else_branch = node[1]
                    tasks.append(("choose", then_branch, else_branch))
                    tasks.append(("eval", condition))
                elif op in ("SUM", "MIN", "MAX"):
                    iterator = argument_nodes(node[1])
                    initial = 0 if op == "SUM" else None
                    tasks.append(("aggregate", op, iterator, initial))
                else:
                    tasks.append(("left_done", op, node[2]))
                    tasks.append(("eval", node[1]))

            elif kind == "negate":
                value = values.pop()
                values.append(value if isinstance(value, str) else -value)

            elif kind == "choose":
                condition = values.pop()
                if isinstance(condition, str):
                    values.append(condition)
                else:
                    branch = task[1] if condition else task[2]
                    tasks.append(("eval", branch))

            elif kind == "left_done":
                left = values.pop()
                if isinstance(left, str):
                    values.append(left)
                else:
                    tasks.append(("right_done", task[1], left))
                    tasks.append(("eval", task[2]))

            elif kind == "right_done":
                right = values.pop()
                if isinstance(right, str):
                    values.append(right)
                    continue

                op, left = task[1], task[2]
                if op == "+":
                    value = left + right
                elif op == "-":
                    value = left - right
                elif op == "*":
                    value = left * right
                elif op == "/":
                    if right == 0:
                        value = "#DIV/0!"
                    else:
                        value = abs(left) // abs(right)
                        if (left < 0) != (right < 0):
                            value = -value
                elif op == "=":
                    value = int(left == right)
                elif op == "<>":
                    value = int(left != right)
                elif op == "<":
                    value = int(left < right)
                elif op == "<=":
                    value = int(left <= right)
                elif op == ">":
                    value = int(left > right)
                else:  # >=
                    value = int(left >= right)
                values.append(value)

            elif kind == "aggregate":
                function, iterator, accumulated = task[1:]
                try:
                    node = next(iterator)
                except StopIteration:
                    values.append(0 if accumulated is None else accumulated)
                else:
                    tasks.append(
                        ("aggregate_value", function, iterator, accumulated)
                    )
                    tasks.append(("eval", node))

            elif kind == "aggregate_value":
                value = values.pop()
                if isinstance(value, str):
                    values.append(value)
                    continue

                function, iterator, accumulated = task[1:]
                if function == "SUM":
                    accumulated += value
                elif accumulated is None:
                    accumulated = value
                elif function == "MIN":
                    accumulated = min(accumulated, value)
                else:
                    accumulated = max(accumulated, value)
                tasks.append(("aggregate", function, iterator, accumulated))

    return {name: results[name] for name in cells}
